INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Suman sa Lihiya', 'Dessert', '30 min', 'Medium', '', '1 person', '400 kcal', NULL, '[{"name": "1/2 cups glutinous rice", "description": "1/2 cups glutinous rice"}, {"name": "1/4 tbsp lye water", "description": "1/4 tbsp lye water"}, {"name": "1 cups water", "description": "1 cups water"}, {"name": "Banana leaves for wrapping", "description": "Banana leaves for wrapping"}, {"name": "Brown sugar or latik for serving", "description": "Brown sugar or latik for serving"}, {"name": "Glutinous Rice -> short-grain rice", "description": "Glutinous Rice -> short-grain rice"}, {"name": "Lye Water -> food-grade lye water is essential; do not substitute with household chemicals", "description": "Lye Water -> food-grade lye water is essential; do not substitute with household chemicals"}, {"name": "Banana Leaves -> parchment paper for lining", "description": "Banana Leaves -> parchment paper for lining"}, {"name": "Brown Sugar -> white sugar", "description": "Brown Sugar -> white sugar"}]'::jsonb, '[{"title": "Step 1", "description": "Wash the glutinous rice thoroughly."}, {"title": "Step 2", "description": "Soak the rice in water mixed with lye water for 2 hours."}, {"title": "Step 3", "description": "Drain the rice well."}, {"title": "Step 4", "description": "Wrap portions of the rice in banana leaves and tie securely."}, {"title": "Step 5", "description": "Boil for 11/2–2 hours until tender."}, {"title": "Step 6", "description": "Remove and drain."}, {"title": "Step 7", "description": "Serve with brown sugar or latik."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Ginataang Halo-Halo', 'Dessert', '30 min', 'Medium', '', '1 person', '650 kcal', NULL, '[{"name": "1/2 cups coconut milk", "description": "1/2 cups coconut milk"}, {"name": "1/4 cup coconut cream", "description": "1/4 cup coconut cream"}, {"name": "1/2 saba bananas, sliced", "description": "1/2 saba bananas, sliced"}, {"name": "1/4 cup sweet potatoes, cubed", "description": "1/4 cup sweet potatoes, cubed"}, {"name": "1/4 cup jackfruit strips", "description": "1/4 cup jackfruit strips"}, {"name": "1/8 cup cooked tapioca pearls", "description": "1/8 cup cooked tapioca pearls"}, {"name": "1/8 cup glutinous rice balls", "description": "1/8 cup glutinous rice balls"}, {"name": "1/8 cup brown sugar", "description": "1/8 cup brown sugar"}, {"name": "Coconut Milk -> evaporated milk or fresh milk", "description": "Coconut Milk -> evaporated milk or fresh milk"}, {"name": "Coconut Cream -> thick coconut milk or all-purpose cream", "description": "Coconut Cream -> thick coconut milk or all-purpose cream"}, {"name": "Saba Bananas -> ripe plantain", "description": "Saba Bananas -> ripe plantain"}, {"name": "Sweet Potatoes -> pumpkin or another sweet potato variety", "description": "Sweet Potatoes -> pumpkin or another sweet potato variety"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the coconut milk in a saucepan."}, {"title": "Step 2", "description": "Add the sweet potatoes and cook until almost tender."}, {"title": "Step 3", "description": "Stir in the glutinous rice balls and cook until they float."}, {"title": "Step 4", "description": "Add the saba bananas, jackfruit, and brown sugar."}, {"title": "Step 5", "description": "Mix in the cooked tapioca pearls."}, {"title": "Step 6", "description": "Pour in the coconut cream and simmer for 3–5 minutes."}, {"title": "Step 7", "description": "Serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Minatamis na Kamoteng Kahoy', 'Dessert', '30 min', 'Easy', '', '1 person', '500 kcal', NULL, '[{"name": "1/4 kg cassava, peeled and sliced", "description": "1/4 kg cassava, peeled and sliced"}, {"name": "1/4 cup brown sugar", "description": "1/4 cup brown sugar"}, {"name": "1 cups water", "description": "1 cups water"}, {"name": "1/4 pandan leaf", "description": "1/4 pandan leaf"}, {"name": "1/4 tsp vanilla extract (optional)", "description": "1/4 tsp vanilla extract (optional)"}, {"name": "Brown Sugar -> white sugar", "description": "Brown Sugar -> white sugar"}, {"name": "Pandan Leaf -> pandan extract or vanilla", "description": "Pandan Leaf -> pandan extract or vanilla"}, {"name": "Vanilla Extract -> vanilla essence or omit", "description": "Vanilla Extract -> vanilla essence or omit"}]'::jsonb, '[{"title": "Step 1", "description": "Place the water, brown sugar, and pandan leaf in a pot."}, {"title": "Step 2", "description": "Bring to a boil until the sugar dissolves."}, {"title": "Step 3", "description": "Add the cassava pieces."}, {"title": "Step 4", "description": "Simmer until the cassava becomes tender."}, {"title": "Step 5", "description": "Stir in the vanilla extract if desired."}, {"title": "Step 6", "description": "Remove from the heat."}, {"title": "Step 7", "description": "Serve warm or chilled."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Buko Pandan Ice Candy', 'Dessert', '30 min', 'Easy', '', '1 person', '300 kcal', NULL, '[{"name": "1/2 cups young coconut strips", "description": "1/2 cups young coconut strips"}, {"name": "1/4 cup evaporated milk", "description": "1/4 cup evaporated milk"}, {"name": "1/4 cup coconut milk", "description": "1/4 cup coconut milk"}, {"name": "1/8 cup condensed milk", "description": "1/8 cup condensed milk"}, {"name": "1/4 tsp pandan flavoring", "description": "1/4 tsp pandan flavoring"}, {"name": "Ice candy plastic bags", "description": "Ice candy plastic bags"}, {"name": "Young Coconut -> canned young coconut, drained", "description": "Young Coconut -> canned young coconut, drained"}, {"name": "Evaporated Milk -> fresh milk", "description": "Evaporated Milk -> fresh milk"}, {"name": "Coconut Milk -> evaporated milk or fresh milk", "description": "Coconut Milk -> evaporated milk or fresh milk"}, {"name": "Condensed Milk -> evaporated milk + sugar", "description": "Condensed Milk -> evaporated milk + sugar"}]'::jsonb, '[{"title": "Step 1", "description": "Combine the evaporated milk, coconut milk, condensed milk, and pandan flavoring."}, {"title": "Step 2", "description": "Stir until well mixed."}, {"title": "Step 3", "description": "Add the young coconut strips."}, {"title": "Step 4", "description": "Pour the mixture into ice candy bags."}, {"title": "Step 5", "description": "Tie the bags securely."}, {"title": "Step 6", "description": "Freeze overnight."}, {"title": "Step 7", "description": "Serve frozen."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Saging na May Latik', 'Dessert', '30 min', 'Easy', '', '1 person', '500 kcal', NULL, '[{"name": "1.5 ripe saba bananas", "description": "1.5 ripe saba bananas"}, {"name": "1/2 cups coconut milk", "description": "1/2 cups coconut milk"}, {"name": "1/8 cup brown sugar", "description": "1/8 cup brown sugar"}, {"name": "1/4 cup coconut cream", "description": "1/4 cup coconut cream"}, {"name": "1/8 tsp salt", "description": "1/8 tsp salt"}, {"name": "Saba Bananas -> ripe plantain", "description": "Saba Bananas -> ripe plantain"}, {"name": "Coconut Milk -> evaporated milk or fresh milk", "description": "Coconut Milk -> evaporated milk or fresh milk"}, {"name": "Brown Sugar -> white sugar", "description": "Brown Sugar -> white sugar"}, {"name": "Coconut Cream -> thick coconut milk or all-purpose cream", "description": "Coconut Cream -> thick coconut milk or all-purpose cream"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the coconut milk in a saucepan."}, {"title": "Step 2", "description": "Add the brown sugar and salt."}, {"title": "Step 3", "description": "Place the saba bananas into the mixture."}, {"title": "Step 4", "description": "Simmer until the bananas are tender."}, {"title": "Step 5", "description": "Cook the coconut cream separately until it forms golden latik."}, {"title": "Step 6", "description": "Spoon the latik over the cooked bananas."}, {"title": "Step 7", "description": "Serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Ube Buchi', 'Dessert', '30 min', 'Medium', '', '1 person', '600 kcal', NULL, '[{"name": "1/2 cups glutinous rice flour", "description": "1/2 cups glutinous rice flour"}, {"name": "3/16 cup warm water", "description": "3/16 cup warm water"}, {"name": "1/4 cup ube halaya", "description": "1/4 cup ube halaya"}, {"name": "1/4 cup sesame seeds", "description": "1/4 cup sesame seeds"}, {"name": "Cooking oil for frying", "description": "Cooking oil for frying"}, {"name": "Glutinous Rice Flour -> rice flour + a little cornstarch", "description": "Glutinous Rice Flour -> rice flour + a little cornstarch"}, {"name": "Ube Halaya -> mashed purple sweet potato + sugar", "description": "Ube Halaya -> mashed purple sweet potato + sugar"}]'::jsonb, '[{"title": "Step 1", "description": "Mix the glutinous rice flour and warm water into a smooth dough."}, {"title": "Step 2", "description": "Divide the dough into equal portions."}, {"title": "Step 3", "description": "Flatten each piece and fill with ube halaya."}, {"title": "Step 4", "description": "Seal and roll into balls."}, {"title": "Step 5", "description": "Coat each ball with sesame seeds."}, {"title": "Step 6", "description": "Deep-fry over low to medium heat until golden brown."}, {"title": "Step 7", "description": "Drain excess oil and serve warm."}]'::jsonb);

