INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Espasol', 'Dessert', '30 min', 'Medium', '', '1 person', '450 kcal', NULL, '[{"name": "1/2 cups glutinous rice flour", "description": "1/2 cups glutinous rice flour"}, {"name": "1/2 cups coconut milk", "description": "1/2 cups coconut milk"}, {"name": "3/16 cup sugar", "description": "3/16 cup sugar"}, {"name": "1/8 cup toasted rice flour", "description": "1/8 cup toasted rice flour"}, {"name": "1/16 tsp salt", "description": "1/16 tsp salt"}, {"name": "Glutinous Rice Flour -> rice flour + a little cornstarch", "description": "Glutinous Rice Flour -> rice flour + a little cornstarch"}, {"name": "Coconut Milk -> evaporated milk or fresh milk", "description": "Coconut Milk -> evaporated milk or fresh milk"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the coconut milk in a saucepan over low heat."}, {"title": "Step 2", "description": "Add the sugar and salt, stirring until dissolved."}, {"title": "Step 3", "description": "Gradually add the glutinous rice flour while stirring continuously."}, {"title": "Step 4", "description": "Cook until the mixture becomes thick and smooth."}, {"title": "Step 5", "description": "Transfer to a tray dusted with toasted rice flour."}, {"title": "Step 6", "description": "Roll into logs and coat with more toasted rice flour."}, {"title": "Step 7", "description": "Slice into serving pieces and serve."}]'::jsonb);

