INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Turon', 'Snack', '30 min', 'Easy', '', '1 person', '250 kcal', NULL, '[{"name": "6 ripe saba bananas, halved lengthwise", "description": "6 ripe saba bananas, halved lengthwise"}, {"name": "1 cup ripe langka (jackfruit), sliced", "description": "1 cup ripe langka (jackfruit), sliced"}, {"name": "12 lumpia wrappers", "description": "12 lumpia wrappers"}, {"name": "1 cup brown sugar", "description": "1 cup brown sugar"}, {"name": "Cooking oil for frying", "description": "Cooking oil for frying"}, {"name": "Water for sealing wrappers", "description": "Water for sealing wrappers"}]'::jsonb, '[{"title": "Step 1", "description": "Roll each banana in brown sugar until coated."}, {"title": "Step 2", "description": "Place one banana and a few slices of jackfruit on a lumpia wrapper."}, {"title": "Step 3", "description": "Fold the sides inward and roll tightly."}, {"title": "Step 4", "description": "Seal the edge with water."}, {"title": "Step 5", "description": "Heat oil over medium heat."}, {"title": "Step 6", "description": "Fry the turon until golden brown and caramelized, about 5–7 minutes."}, {"title": "Step 7", "description": "Drain on paper towels and serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
