INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Nilupak na Kamoteng Kahoy', 'Snack', '30 min', 'Easy', '', '1 person', '300 kcal', NULL, '[{"name": "1 kg cassava, peeled", "description": "1 kg cassava, peeled"}, {"name": "1/4 cup butter", "description": "1/4 cup butter"}, {"name": "1/2 cup condensed milk", "description": "1/2 cup condensed milk"}, {"name": "1 cup grated coconut", "description": "1 cup grated coconut"}, {"name": "1/2 tsp salt", "description": "1/2 tsp salt"}]'::jsonb, '[{"title": "Step 1", "description": "Boil the cassava until fork-tender."}, {"title": "Step 2", "description": "Drain and mash until smooth."}, {"title": "Step 3", "description": "Add the butter, condensed milk, and salt."}, {"title": "Step 4", "description": "Continue mashing until well combined."}, {"title": "Step 5", "description": "Transfer to a serving plate."}, {"title": "Step 6", "description": "Top generously with grated coconut."}, {"title": "Step 7", "description": "Serve warm or chilled."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Tupig', 'Snack', '30 min', 'Easy', '', '1 person', '250 kcal', NULL, '[{"name": "2 cups glutinous rice flour", "description": "2 cups glutinous rice flour"}, {"name": "1 cup brown sugar", "description": "1 cup brown sugar"}, {"name": "1 cup grated young coconut", "description": "1 cup grated young coconut"}, {"name": "1 cup coconut milk", "description": "1 cup coconut milk"}, {"name": "1 tsp vanilla extract", "description": "1 tsp vanilla extract"}, {"name": "Banana leaves, wilted", "description": "Banana leaves, wilted"}, {"name": "Kitchen string", "description": "Kitchen string"}]'::jsonb, '[{"title": "Step 1", "description": "In a bowl, combine the glutinous rice flour, brown sugar, grated coconut, coconut milk, and vanilla extract."}, {"title": "Step 2", "description": "Mix until a smooth batter forms."}, {"title": "Step 3", "description": "Place about 1/4 cup of the mixture onto a wilted banana leaf."}, {"title": "Step 4", "description": "Fold the banana leaf tightly and secure it with kitchen string."}, {"title": "Step 5", "description": "Preheat a grill over medium heat."}, {"title": "Step 6", "description": "Grill each tupig for 15–20 minutes, turning occasionally until lightly charred."}, {"title": "Step 7", "description": "Serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Bibingkang Malagkit', 'Snack', '30 min', 'Easy', '', '1 person', '350 kcal', NULL, '[{"name": "2 cups glutinous rice", "description": "2 cups glutinous rice"}, {"name": "2 cups coconut milk", "description": "2 cups coconut milk"}, {"name": "11/2 cups brown sugar", "description": "11/2 cups brown sugar"}, {"name": "1 cup coconut cream", "description": "1 cup coconut cream"}, {"name": "1/2 tsp salt", "description": "1/2 tsp salt"}, {"name": "Banana leaves (optional)", "description": "Banana leaves (optional)"}]'::jsonb, '[{"title": "Step 1", "description": "Cook the glutinous rice until tender."}, {"title": "Step 2", "description": "Simmer the coconut milk with half of the brown sugar."}, {"title": "Step 3", "description": "Mix the cooked rice into the coconut mixture."}, {"title": "Step 4", "description": "Transfer to a baking dish lined with banana leaves."}, {"title": "Step 5", "description": "Simmer the coconut cream with the remaining brown sugar until thick."}, {"title": "Step 6", "description": "Spread the topping over the rice mixture."}, {"title": "Step 7", "description": "Bake at 180°C (350°F) for 20–25 minutes until lightly browned."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
