INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Minatamis na Saging', 'Snack', '30 min', 'Easy', '', '1 person', '250 kcal', NULL, '[{"name": "6 ripe saba bananas", "description": "6 ripe saba bananas"}, {"name": "1 cup brown sugar", "description": "1 cup brown sugar"}, {"name": "2 cups water", "description": "2 cups water"}, {"name": "1 pandan leaf (optional)", "description": "1 pandan leaf (optional)"}, {"name": "1/2 tsp vanilla extract (optional)", "description": "1/2 tsp vanilla extract (optional)"}]'::jsonb, '[{"title": "Step 1", "description": "Peel the saba bananas and cut them in half if large."}, {"title": "Step 2", "description": "Combine the water, brown sugar, and pandan leaf in a saucepan."}, {"title": "Step 3", "description": "Bring the mixture to a boil until the sugar dissolves."}, {"title": "Step 4", "description": "Add the saba bananas to the syrup."}, {"title": "Step 5", "description": "Simmer over low heat for 15–20 minutes until the bananas are tender."}, {"title": "Step 6", "description": "Remove the pandan leaf and stir in the vanilla extract, if using."}, {"title": "Step 7", "description": "Serve warm on its own or with crushed ice and evaporated milk."}]'::jsonb);

