INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Empanadang Gulay', 'Snack', '30 min', 'Easy', '', '1 person', '280 kcal', NULL, '[{"name": "10 empanada dough wrappers", "description": "10 empanada dough wrappers"}, {"name": "1 cup cabbage, shredded", "description": "1 cup cabbage, shredded"}, {"name": "1/2 cup carrots, diced", "description": "1/2 cup carrots, diced"}, {"name": "1/2 cup potatoes, diced", "description": "1/2 cup potatoes, diced"}, {"name": "1/4 cup green peas", "description": "1/4 cup green peas"}, {"name": "1 onion, chopped", "description": "1 onion, chopped"}, {"name": "3 cloves garlic, minced", "description": "3 cloves garlic, minced"}, {"name": "2 tbsp cooking oil", "description": "2 tbsp cooking oil"}, {"name": "Salt and pepper to taste", "description": "Salt and pepper to taste"}, {"name": "Oil for frying (optional)", "description": "Oil for frying (optional)"}]'::jsonb, '[{"title": "Step 1", "description": "Heat oil and sauté the garlic and onion until fragrant."}, {"title": "Step 2", "description": "Add the potatoes and carrots; cook until tender."}, {"title": "Step 3", "description": "Stir in the cabbage and green peas. Season with salt and pepper."}, {"title": "Step 4", "description": "Allow the filling to cool completely."}, {"title": "Step 5", "description": "Place the filling on each empanada wrapper and fold into a half-moon shape. Seal the edges with a fork."}, {"title": "Step 6", "description": "Bake at 190°C (375°F) for 25–30 minutes, or deep-fry until golden brown."}, {"title": "Step 7", "description": "Serve warm with banana ketchup or vinegar."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Nilupak na Saging', 'Snack', '30 min', 'Easy', '', '1 person', '350 kcal', NULL, '[{"name": "8 ripe saba bananas", "description": "8 ripe saba bananas"}, {"name": "1/4 cup butter", "description": "1/4 cup butter"}, {"name": "1/2 cup condensed milk", "description": "1/2 cup condensed milk"}, {"name": "1 cup freshly grated coconut", "description": "1 cup freshly grated coconut"}, {"name": "1/4 tsp salt", "description": "1/4 tsp salt"}]'::jsonb, '[{"title": "Step 1", "description": "Boil the saba bananas until tender, about 15–20 minutes."}, {"title": "Step 2", "description": "Peel the bananas while still warm."}, {"title": "Step 3", "description": "Mash the bananas until smooth using a mortar and pestle or potato masher."}, {"title": "Step 4", "description": "Add the butter, condensed milk, and salt."}, {"title": "Step 5", "description": "Continue mashing until well combined."}, {"title": "Step 6", "description": "Transfer to a serving plate and top with grated coconut."}, {"title": "Step 7", "description": "Serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
