INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Sinapot', 'Snack', '30 min', 'Easy', '', '1 person', '180 kcal', NULL, '[{"name": "8 ripe saba bananas", "description": "8 ripe saba bananas"}, {"name": "Water for steaming", "description": "Water for steaming"}]'::jsonb, '[{"title": "Step 1", "description": "Wash the saba bananas thoroughly."}, {"title": "Step 2", "description": "Arrange them in a steamer basket."}, {"title": "Step 3", "description": "Steam over boiling water for 20–25 minutes."}, {"title": "Step 4", "description": "Check that the bananas are soft."}, {"title": "Step 5", "description": "Remove from the steamer."}, {"title": "Step 6", "description": "Peel while still warm."}, {"title": "Step 7", "description": "Serve as is or with grated coconut."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Adobong Mani', 'Snack', '30 min', 'Easy', '', '1 person', '300 kcal', NULL, '[{"name": "500g raw peanuts", "description": "500g raw peanuts"}, {"name": "6 cloves garlic, sliced", "description": "6 cloves garlic, sliced"}, {"name": "3 cups cooking oil", "description": "3 cups cooking oil"}, {"name": "1 tsp salt", "description": "1 tsp salt"}]'::jsonb, '[{"title": "Step 1", "description": "Heat the oil over low heat."}, {"title": "Step 2", "description": "Fry the garlic until golden and remove."}, {"title": "Step 3", "description": "Add the peanuts and fry slowly until cooked."}, {"title": "Step 4", "description": "Remove and drain well."}, {"title": "Step 5", "description": "Toss with salt."}, {"title": "Step 6", "description": "Mix in the fried garlic."}, {"title": "Step 7", "description": "Cool completely before serving."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Pastillas de Leche', 'Snack', '30 min', 'Easy', '', '1 person', '220 kcal', NULL, '[{"name": "2 cups powdered milk", "description": "2 cups powdered milk"}, {"name": "1 can (300ml) condensed milk", "description": "1 can (300ml) condensed milk"}, {"name": "1/2 cup white sugar", "description": "1/2 cup white sugar"}]'::jsonb, '[{"title": "Step 1", "description": "Combine the powdered milk and condensed milk."}, {"title": "Step 2", "description": "Mix until a soft dough forms."}, {"title": "Step 3", "description": "Scoop small portions and roll into logs."}, {"title": "Step 4", "description": "Roll each piece in sugar."}, {"title": "Step 5", "description": "Arrange on a tray."}, {"title": "Step 6", "description": "Chill for 30 minutes."}, {"title": "Step 7", "description": "Wrap individually and serve."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Yema Balls', 'Snack', '30 min', 'Easy', '', '1 person', '250 kcal', NULL, '[{"name": "1 can condensed milk", "description": "1 can condensed milk"}, {"name": "4 egg yolks", "description": "4 egg yolks"}, {"name": "2 tbsp butter", "description": "2 tbsp butter"}, {"name": "1/2 cup white sugar", "description": "1/2 cup white sugar"}]'::jsonb, '[{"title": "Step 1", "description": "Combine the condensed milk and egg yolks in a saucepan."}, {"title": "Step 2", "description": "Cook over low heat while stirring continuously."}, {"title": "Step 3", "description": "Add the butter and continue cooking until thick."}, {"title": "Step 4", "description": "Allow the mixture to cool completely."}, {"title": "Step 5", "description": "Scoop small portions and roll into balls."}, {"title": "Step 6", "description": "Coat each ball with sugar."}, {"title": "Step 7", "description": "Refrigerate before serving."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Ginanggang', 'Snack', '30 min', 'Easy', '', '1 person', '250 kcal', NULL, '[{"name": "6 semi-ripe saba bananas", "description": "6 semi-ripe saba bananas"}, {"name": "1/4 cup margarine, melted", "description": "1/4 cup margarine, melted"}, {"name": "1/4 cup white sugar", "description": "1/4 cup white sugar"}, {"name": "Bamboo skewers", "description": "Bamboo skewers"}]'::jsonb, '[{"title": "Step 1", "description": "Peel the saba bananas and insert each onto a bamboo skewer."}, {"title": "Step 2", "description": "Preheat a charcoal grill over medium heat."}, {"title": "Step 3", "description": "Grill the bananas for 5–7 minutes, turning occasionally."}, {"title": "Step 4", "description": "Brush each banana generously with melted margarine."}, {"title": "Step 5", "description": "Continue grilling until lightly caramelized."}, {"title": "Step 6", "description": "Sprinkle with sugar while still hot."}, {"title": "Step 7", "description": "Serve immediately."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Nilasing na Saging', 'Snack', '30 min', 'Easy', '', '1 person', '300 kcal', NULL, '[{"name": "6 ripe saba bananas", "description": "6 ripe saba bananas"}, {"name": "1 cup all-purpose flour", "description": "1 cup all-purpose flour"}, {"name": "1 egg", "description": "1 egg"}, {"name": "1/2 cup fresh milk", "description": "1/2 cup fresh milk"}, {"name": "2 tbsp sugar", "description": "2 tbsp sugar"}, {"name": "1/2 tsp vanilla extract", "description": "1/2 tsp vanilla extract"}, {"name": "1/2 tsp ground cinnamon", "description": "1/2 tsp ground cinnamon"}, {"name": "Cooking oil for frying", "description": "Cooking oil for frying"}]'::jsonb, '[{"title": "Step 1", "description": "Peel the saba bananas and cut them in half lengthwise."}, {"title": "Step 2", "description": "In a bowl, combine the flour, egg, milk, sugar, vanilla, and cinnamon."}, {"title": "Step 3", "description": "Mix until smooth."}, {"title": "Step 4", "description": "Dip each banana into the batter."}, {"title": "Step 5", "description": "Fry in hot oil until golden brown."}, {"title": "Step 6", "description": "Drain on paper towels."}, {"title": "Step 7", "description": "Serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Pritong Mais', 'Snack', '30 min', 'Easy', '', '1 person', '280 kcal', NULL, '[{"name": "2 cups fresh corn kernels", "description": "2 cups fresh corn kernels"}, {"name": "1 cup all-purpose flour", "description": "1 cup all-purpose flour"}, {"name": "1/4 cup cornstarch", "description": "1/4 cup cornstarch"}, {"name": "1 egg", "description": "1 egg"}, {"name": "3/4 cup water", "description": "3/4 cup water"}, {"name": "1/2 tsp salt", "description": "1/2 tsp salt"}, {"name": "1/2 tsp pepper", "description": "1/2 tsp pepper"}, {"name": "Cooking oil for frying", "description": "Cooking oil for frying"}]'::jsonb, '[{"title": "Step 1", "description": "Mix the flour, cornstarch, egg, water, salt, and pepper."}, {"title": "Step 2", "description": "Fold in the corn kernels."}, {"title": "Step 3", "description": "Heat oil over medium heat."}, {"title": "Step 4", "description": "Scoop spoonfuls of the batter into the hot oil."}, {"title": "Step 5", "description": "Fry until golden brown and crispy."}, {"title": "Step 6", "description": "Drain excess oil."}, {"title": "Step 7", "description": "Serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Kamote Balls', 'Snack', '30 min', 'Easy', '', '1 person', '300 kcal', NULL, '[{"name": "500g sweet potatoes", "description": "500g sweet potatoes"}, {"name": "1 cup all-purpose flour", "description": "1 cup all-purpose flour"}, {"name": "1/4 cup sugar", "description": "1/4 cup sugar"}, {"name": "1 egg", "description": "1 egg"}, {"name": "1/2 tsp baking powder", "description": "1/2 tsp baking powder"}, {"name": "Cooking oil for frying", "description": "Cooking oil for frying"}]'::jsonb, '[{"title": "Step 1", "description": "Boil the sweet potatoes until tender."}, {"title": "Step 2", "description": "Mash until smooth."}, {"title": "Step 3", "description": "Add the flour, sugar, egg, and baking powder."}, {"title": "Step 4", "description": "Mix until a soft dough forms."}, {"title": "Step 5", "description": "Shape into small balls."}, {"title": "Step 6", "description": "Fry until golden brown."}, {"title": "Step 7", "description": "Drain and serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Puto Pandan', 'Snack', '30 min', 'Easy', '', '1 person', '180 kcal', NULL, '[{"name": "2 cups all-purpose flour", "description": "2 cups all-purpose flour"}, {"name": "1 cup sugar", "description": "1 cup sugar"}, {"name": "1 tbsp baking powder", "description": "1 tbsp baking powder"}, {"name": "1 cup pandan juice", "description": "1 cup pandan juice"}, {"name": "2 eggs", "description": "2 eggs"}, {"name": "1/4 cup melted butter", "description": "1/4 cup melted butter"}, {"name": "Cheese cubes for topping", "description": "Cheese cubes for topping"}]'::jsonb, '[{"title": "Step 1", "description": "Combine the flour, sugar, and baking powder."}, {"title": "Step 2", "description": "Add the pandan juice, eggs, and butter."}, {"title": "Step 3", "description": "Mix until smooth."}, {"title": "Step 4", "description": "Fill greased puto molds three-fourths full."}, {"title": "Step 5", "description": "Place a cheese cube on top."}, {"title": "Step 6", "description": "Steam for 15 minutes."}, {"title": "Step 7", "description": "Remove from the molds and serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Ube Halaya', 'Snack', '30 min', 'Easy', '', '1 person', '300 kcal', NULL, '[{"name": "1 kg purple yam (ube), boiled and grated", "description": "1 kg purple yam (ube), boiled and grated"}, {"name": "1 can condensed milk", "description": "1 can condensed milk"}, {"name": "1 can evaporated milk", "description": "1 can evaporated milk"}, {"name": "1/2 cup butter", "description": "1/2 cup butter"}, {"name": "1/2 cup sugar", "description": "1/2 cup sugar"}]'::jsonb, '[{"title": "Step 1", "description": "Combine the grated ube, condensed milk, evaporated milk, and sugar in a pan."}, {"title": "Step 2", "description": "Cook over low heat while stirring continuously."}, {"title": "Step 3", "description": "Add the butter gradually."}, {"title": "Step 4", "description": "Continue cooking until thick and smooth."}, {"title": "Step 5", "description": "Transfer to a greased serving dish."}, {"title": "Step 6", "description": "Brush the top with butter."}, {"title": "Step 7", "description": "Cool before serving."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Puto Calasiao', 'Snack', '30 min', 'Easy', '', '1 person', '220 kcal', NULL, '[{"name": "2 cups rice flour", "description": "2 cups rice flour"}, {"name": "3/4 cup sugar", "description": "3/4 cup sugar"}, {"name": "1 cup water", "description": "1 cup water"}, {"name": "1 tsp yeast", "description": "1 tsp yeast"}, {"name": "1/4 tsp salt", "description": "1/4 tsp salt"}]'::jsonb, '[{"title": "Step 1", "description": "Dissolve the yeast in warm water."}, {"title": "Step 2", "description": "Combine the rice flour, sugar, and salt."}, {"title": "Step 3", "description": "Add the yeast mixture and mix thoroughly."}, {"title": "Step 4", "description": "Let the batter ferment for 2–3 hours."}, {"title": "Step 5", "description": "Pour into small molds."}, {"title": "Step 6", "description": "Steam for 15–20 minutes."}, {"title": "Step 7", "description": "Cool slightly before serving."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Bibingkang Galapong', 'Snack', '30 min', 'Easy', '', '1 person', '300 kcal', NULL, '[{"name": "2 cups galapong (ground soaked rice)", "description": "2 cups galapong (ground soaked rice)"}, {"name": "1 cup coconut milk", "description": "1 cup coconut milk"}, {"name": "1/2 cup sugar", "description": "1/2 cup sugar"}, {"name": "2 eggs", "description": "2 eggs"}, {"name": "1 tsp baking powder", "description": "1 tsp baking powder"}, {"name": "2 salted eggs, sliced", "description": "2 salted eggs, sliced"}, {"name": "1/2 cup grated coconut", "description": "1/2 cup grated coconut"}, {"name": "Butter for brushing", "description": "Butter for brushing"}]'::jsonb, '[{"title": "Step 1", "description": "Preheat the oven to 180°C (350°F)."}, {"title": "Step 2", "description": "Mix the galapong, coconut milk, sugar, eggs, and baking powder until smooth."}, {"title": "Step 3", "description": "Pour the batter into a greased baking pan lined with banana leaves, if available."}, {"title": "Step 4", "description": "Arrange the sliced salted eggs on top."}, {"title": "Step 5", "description": "Bake for 25–30 minutes or until lightly golden."}, {"title": "Step 6", "description": "Brush with butter and sprinkle with grated coconut."}, {"title": "Step 7", "description": "Serve warm."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Ube Leche Flan Cake', 'Snack', '30 min', 'Easy', '', '1 person', '450 kcal', NULL, '[{"name": "1 prepared ube cake batter", "description": "1 prepared ube cake batter"}, {"name": "1 prepared leche flan", "description": "1 prepared leche flan"}, {"name": "2 eggs", "description": "2 eggs"}, {"name": "1/2 cup evaporated milk", "description": "1/2 cup evaporated milk"}, {"name": "Butter for greasing the pan", "description": "Butter for greasing the pan"}]'::jsonb, '[{"title": "Step 1", "description": "Preheat the oven to 175°C (350°F)."}, {"title": "Step 2", "description": "Grease a round cake pan with butter."}, {"title": "Step 3", "description": "Pour the ube cake batter into the pan."}, {"title": "Step 4", "description": "Carefully place the prepared leche flan on top of the batter."}, {"title": "Step 5", "description": "Bake for 45–50 minutes or until a toothpick inserted into the cake comes out clean."}, {"title": "Step 6", "description": "Cool completely before inverting onto a serving plate."}, {"title": "Step 7", "description": "Slice and serve chilled or at room temperature."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Mango Sago', 'Snack', '30 min', 'Easy', '', '1 person', '350 kcal', NULL, '[{"name": "2 ripe mangoes, diced", "description": "2 ripe mangoes, diced"}, {"name": "1 cup cooked small sago pearls", "description": "1 cup cooked small sago pearls"}, {"name": "1 cup all-purpose cream", "description": "1 cup all-purpose cream"}, {"name": "1/2 cup condensed milk", "description": "1/2 cup condensed milk"}, {"name": "1/2 cup evaporated milk", "description": "1/2 cup evaporated milk"}]'::jsonb, '[{"title": "Step 1", "description": "Cook the sago pearls according to the package instructions and drain."}, {"title": "Step 2", "description": "Combine the all-purpose cream, condensed milk, and evaporated milk."}, {"title": "Step 3", "description": "Add the cooked sago pearls and diced mangoes."}, {"title": "Step 4", "description": "Fold gently until well combined."}, {"title": "Step 5", "description": "Transfer to a serving bowl."}, {"title": "Step 6", "description": "Refrigerate for at least 2 hours."}, {"title": "Step 7", "description": "Serve chilled."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Pineapple Macapuno Delight', 'Snack', '30 min', 'Easy', '', '1 person', '380 kcal', NULL, '[{"name": "2 cups pineapple chunks, drained", "description": "2 cups pineapple chunks, drained"}, {"name": "1 cup macapuno strings", "description": "1 cup macapuno strings"}, {"name": "1 cup all-purpose cream", "description": "1 cup all-purpose cream"}, {"name": "1 can condensed milk", "description": "1 can condensed milk"}, {"name": "1/2 cup nata de coco", "description": "1/2 cup nata de coco"}]'::jsonb, '[{"title": "Step 1", "description": "Drain the pineapple chunks thoroughly."}, {"title": "Step 2", "description": "Combine the pineapple, macapuno, and nata de coco in a bowl."}, {"title": "Step 3", "description": "Mix the all-purpose cream and condensed milk."}, {"title": "Step 4", "description": "Pour the cream mixture over the fruit."}, {"title": "Step 5", "description": "Fold gently until well combined."}, {"title": "Step 6", "description": "Chill for at least 3 hours."}, {"title": "Step 7", "description": "Serve cold."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Langka Ice Cream', 'Snack', '30 min', 'Easy', '', '1 person', '350 kcal', NULL, '[{"name": "2 cups ripe jackfruit, finely chopped", "description": "2 cups ripe jackfruit, finely chopped"}, {"name": "2 cups all-purpose cream", "description": "2 cups all-purpose cream"}, {"name": "1 can condensed milk", "description": "1 can condensed milk"}, {"name": "1 tsp vanilla extract", "description": "1 tsp vanilla extract"}]'::jsonb, '[{"title": "Step 1", "description": "Blend half of the jackfruit until smooth."}, {"title": "Step 2", "description": "Combine the blended jackfruit, chopped jackfruit, cream, condensed milk, and vanilla."}, {"title": "Step 3", "description": "Mix until well combined."}, {"title": "Step 4", "description": "Transfer to a freezer-safe container."}, {"title": "Step 5", "description": "Cover tightly."}, {"title": "Step 6", "description": "Freeze overnight."}, {"title": "Step 7", "description": "Scoop and serve."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Sweet Potato Halaya', 'Snack', '30 min', 'Easy', '', '1 person', '330 kcal', NULL, '[{"name": "1 kg sweet potatoes, boiled and mashed", "description": "1 kg sweet potatoes, boiled and mashed"}, {"name": "1 can condensed milk", "description": "1 can condensed milk"}, {"name": "1 cup coconut milk", "description": "1 cup coconut milk"}, {"name": "1/4 cup butter", "description": "1/4 cup butter"}, {"name": "1/2 cup sugar", "description": "1/2 cup sugar"}]'::jsonb, '[{"title": "Step 1", "description": "Combine the mashed sweet potatoes and coconut milk in a pan."}, {"title": "Step 2", "description": "Add the condensed milk and sugar."}, {"title": "Step 3", "description": "Cook over low heat while stirring continuously."}, {"title": "Step 4", "description": "Add the butter and continue stirring until thick."}, {"title": "Step 5", "description": "Transfer to a greased serving dish."}, {"title": "Step 6", "description": "Smooth the top with a spatula."}, {"title": "Step 7", "description": "Cool before serving."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Pandan Jelly Delight', 'Snack', '30 min', 'Easy', '', '1 person', '250 kcal', NULL, '[{"name": "1 pack pandan-flavored gelatin", "description": "1 pack pandan-flavored gelatin"}, {"name": "2 cups water", "description": "2 cups water"}, {"name": "1 cup all-purpose cream", "description": "1 cup all-purpose cream"}, {"name": "1/2 cup condensed milk", "description": "1/2 cup condensed milk"}, {"name": "1 cup nata de coco", "description": "1 cup nata de coco"}]'::jsonb, '[{"title": "Step 1", "description": "Prepare the pandan gelatin according to the package directions."}, {"title": "Step 2", "description": "Allow it to cool and set completely."}, {"title": "Step 3", "description": "Cut the jelly into cubes."}, {"title": "Step 4", "description": "Combine the cream and condensed milk."}, {"title": "Step 5", "description": "Fold in the jelly cubes and nata de coco."}, {"title": "Step 6", "description": "Chill for at least 2 hours."}, {"title": "Step 7", "description": "Serve cold."}]'::jsonb);

INSERT INTO public.recipes (title, category, "time", difficulty, image_url, serving, calories, background_color, ingredients, steps)
VALUES ('Caramel Banana Delight', 'Snack', '30 min', 'Easy', '', '1 person', '350 kcal', NULL, '[{"name": "6 ripe saba bananas", "description": "6 ripe saba bananas"}, {"name": "1/2 cup brown sugar", "description": "1/2 cup brown sugar"}, {"name": "2 tbsp butter", "description": "2 tbsp butter"}, {"name": "1 cup whipped cream", "description": "1 cup whipped cream"}, {"name": "1 cup crushed graham crackers", "description": "1 cup crushed graham crackers"}]'::jsonb, '[{"title": "Step 1", "description": "Slice the saba bananas into rounds."}, {"title": "Step 2", "description": "Melt the butter in a pan and add the brown sugar."}, {"title": "Step 3", "description": "Cook until the sugar caramelizes."}, {"title": "Step 4", "description": "Add the bananas and cook for 3–5 minutes."}, {"title": "Step 5", "description": "Allow the bananas to cool slightly."}, {"title": "Step 6", "description": "Layer the caramelized bananas, whipped cream, and crushed graham crackers in serving glasses."}, {"title": "Step 7", "description": "Chill for 1 hour before serving."}]'::jsonb);
